on conflict (country_code, calendar_code, calendar_date)
do update set
  language_code = excluded.language_code,
  feast_rank = excluded.feast_rank,
  saints = excluded.saints,
  title = excluded.title,
  details = excluded.details,
  fasting_note = excluded.fasting_note,
  editorial_source = excluded.editorial_source,
  is_published = excluded.is_published,
  updated_at = timezone('utc', now());

insert into public.calendar_day_translations (
  calendar_day_id, language_code, title, saints, details, fasting_note, editorial_source
)
select id, 'en', title, saints, details, fasting_note, editorial_source || ' · English fallback mirrors Romanian until reviewed'
from public.calendar_days
where country_code = 'MD'
  and calendar_code = 'md-chisinau'
  and calendar_date between '2026-01-01' and '2026-12-31'
on conflict (calendar_day_id, language_code)
do update set
  title = excluded.title,
  saints = excluded.saints,
  details = excluded.details,
  fasting_note = excluded.fasting_note,
  editorial_source = excluded.editorial_source,
  updated_at = timezone('utc', now());

do $$
declare
  v_count integer;
  v_unique integer;
  v_min date;
  v_max date;
begin
  select count(*), count(distinct calendar_date), min(calendar_date), max(calendar_date)
    into v_count, v_unique, v_min, v_max
  from public.calendar_days
  where country_code = 'MD'
    and calendar_code = 'md-chisinau'
    and calendar_date between '2026-01-01' and '2026-12-31';

  if v_count <> 365 or v_unique <> 365 or v_min <> '2026-01-01' or v_max <> '2026-12-31' then
    raise exception 'Invalid Moldova Chisinau reseed: count %, unique %, first %, last %', v_count, v_unique, v_min, v_max;
  end if;
end $$;
